with latest as (select *, row_number() over (partition by product_id order by quantity desc, id) as dedup_rank from order_items qualify dedup_rank = 1) select case when unit_price >= 370 then 'PREMIUM' else 'STANDARD' end as unit_price_tier, percentile_approx(unit_price, array(0.25, 0.5, 0.75)) as unit_price_quartiles, stddev_samp(quantity) as quantity_stddev, round(avg(quantity), 2) as avg_quantity, bit_and(quantity) as quantity_bit_and, round(avg(unit_price), 2) as avg_unit_price, stddev_samp(quantity) as quantity_stddev_2 from latest group by unit_price_tier;
